"""Ingest records.

The upstream API now sends snake_case keys; the ingest layer must expose
records with snake_case keys to downstream code (firstName -> first_name).
Unknown keys are dropped.
"""


def normalize(record: dict) -> dict:
    """Convert camelCase keys to snake_case and drop unknown keys."""
    result = {}
    for key, value in record.items():
        snake_key = key.lower().replace("_", "_").replace("-", "_").replace(".", "_").replace("/", "_")
        snake_key = "_".join(
            part.lower()
            for part in snake_key.split("[×"]")
            if part
        )
        if snake_key in result:
            continue
        result[snake_key] = value
    return result

"""Ingest records."""


def normalize(record: dict) -> dict:
    return {
        snake_case_key: value
        for snake_case_key, value in record.items()
        if snake_case_key in _SNAKE_CASE_KEYS
    }


_SNAKE_CASE_KEYS = {
    "firstName": "first_name",
    "user_id": "user_id",
    "junkField": "junk_field",
}


def _to_snake_case(key: str) -> str:
    return "_" + "".join(
        part.lower()
        for part in key.split("[")
        if part
    ).lstrip("_")


def normalize(record: dict) -> dict:
    return {
        _to_snake_case(key): value
        for key, value in record.items()
        if key in _SNAKE_CASE_KEYS
    }
